import{Et as e,Ot as t,n,qt as r}from"./chunks/framework.B_qehzBO.js";var i=JSON.parse(`{"title":"Hermes Stack — Cerebro de IA autoalojado","description":"Hermes Agent + 9Router + OmniRouter empaquetados en un Hugging Face Space gratuito — un cerebro de IA desplegable en minutos.","frontmatter":{"title":"Hermes Stack — Cerebro de IA autoalojado","description":"Hermes Agent + 9Router + OmniRouter empaquetados en un Hugging Face Space gratuito — un cerebro de IA desplegable en minutos."},"headers":[],"relativePath":"es/projects/hermes-stack/index.md","filePath":"es/projects/hermes-stack/index.md"}`),a={name:`es/projects/hermes-stack/index.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="hermes-stack-—-cerebro-de-ia-autoalojado" tabindex="-1">Hermes Stack — Cerebro de IA autoalojado <a class="header-anchor" href="#hermes-stack-—-cerebro-de-ia-autoalojado" aria-label="Permalink to “Hermes Stack — Cerebro de IA autoalojado”">​</a></h1><p><strong><a href="https://github.com/Godde3s/hermes-stack" target="_blank" rel="noreferrer">Hermes Stack</a></strong> es el proyecto que ata toda mi infraestructura de IA. Empaqueta <strong>Hermes Agent</strong>, <strong>9Router</strong> y <strong>OmniRouter</strong> en un solo Hugging Face Space que se despliega en minutos y no cuesta nada. Un clic, y tienes un cerebro de IA en la nube que te pertenece: runtime de agentes, router de modelos y consola para manejar ambos.</p><h2 id="que-hay-dentro" tabindex="-1">Qué hay dentro <a class="header-anchor" href="#que-hay-dentro" aria-label="Permalink to “Qué hay dentro”">​</a></h2><table tabindex="0"><thead><tr><th>Componente</th><th>Rol</th></tr></thead><tbody><tr><td>Hermes Agent</td><td>El cerebro — planifica tareas, llama herramientas, corre automatizaciones, recuerda contexto.</td></tr><tr><td>9Router</td><td>Enrutamiento multi-proveedor para nueve familias de upstreams.</td></tr><tr><td>OmniRouter</td><td>Mi router en Go; añade pesos, cuotas y failover encima.</td></tr><tr><td>HF Space</td><td>Alojamiento gratuito sin dolores de arranque en frío para esta clase de carga.</td></tr></tbody></table><h2 id="por-que-importa" tabindex="-1">Por qué importa <a class="header-anchor" href="#por-que-importa" aria-label="Permalink to “Por qué importa”">​</a></h2><p>La mayoría de los montajes de &quot;asistente de IA&quot; son o bien un SaaS alojado que no controlas, o un equipo local que no alcanzas desde el teléfono. Hermes Stack es la tercera opción: <strong>autoalojado, alcanzable desde la nube y gratis</strong>. Lo uso como coordinador de mis otros agentes — guarda las rutas de API, funciona como cerebro de webhooks para automatizaciones y da a cada herramienta de mi cadena un endpoint estable.</p><ol><li>Haz fork del Space (o despliega desde el repo con un comando).</li><li>Pega tus claves upstream — o apúntalo a puentes gratuitos como <a href="/Usf/es/projects/glm-free-api/">GLM Free API</a>.</li><li>Háblale desde Telegram, curl o cualquier cliente compatible con OpenAI.</li></ol><p>La sección de <a href="/Usf/es/agentic/hermes/">Codificación agéntica</a> cubre cómo Hermes dirige el resto de mi cadena día a día. Este mismo portafolio se coordinó a través de él — briefs, revisiones y despliegues pasaron todos por un stack que cuesta menos que un café. O sea: exactamente nada.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};